INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122464, 'spa', 'Quitar, deponer', 'Formas causativas del Hafel que significan ''quitar, remover o deponer'', con Dios como agente último. Daniel 2:21 declara que Dios ''quita reyes''; Daniel 5:20 relata cómo la gloria de Belsasar ''fue quitada''; y Daniel 7:12, 26 describen el dominio arrebatado a los reinos bestiales. Se subraya la naturaleza autoritativa y contundente de la acción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122465, 'spa', 'Pasar, cesar', 'Formas intransitivas Qal (Pe''al) que significan ''pasar, desvanecerse o cesar''. Se usan del fuego que pasa sin daño sobre los cuerpos (Dn 3:27), de un reino que se aparta del gobernante (Dn 4:31), de leyes que no pueden ser revocadas (Dn 6:8, 12) y de un dominio que jamás pasará (Dn 7:14). Transmiten el sentido de cesación o transición irreversible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122472, 'spa', 'Adornarse, engalanarse', 'Adornarse o engalanarse con joyas, atavíos o vestiduras decorativas. La acción reflexiva impregna las ocho ocurrencias, ya sea en la preparación nupcial literal (Is 61:10) o en representaciones figuradas de la infidelidad de Israel (Os 2:13, Ez 23:40). En Job 40:10, Dios desafía irónicamente a Job a revestirse de majestad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122480, 'spa', 'Adá (nombre propio)', 'Nombre propio femenino portado por dos mujeres en Génesis: la esposa de Lamec en la genealogía prediluviana (Gn 4:19, 20, 23) y una de las esposas heteas de Esaú (Gn 36:2, 4, 10, 12, 16). Su etimología, derivada de la raíz ''adornar'', presenta a su portadora como un ''ornamento''. BDB también lo vincula con el árabe ''mañana''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122481, 'spa', 'congregación de Israel', 'La congregación o asamblea formal de Israel, el pueblo del pacto reunido en su capacidad cúltica, jurídica y nacional, con 142 de 149 ocurrencias. Casi siempre en constructo con ''Israel'' o ''los hijos de Israel'', funciona como término cuasi-técnico en la legislación sacerdotal para el pueblo destinatario de los mandatos divinos (Lv 4:15; 8:3-4; Nm 1:2; 14:1-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122487, 'spa', 'banda, grupo hostil', 'Un grupo menor, banda o facción de personas, a menudo con matices hostiles o conspiratorios, en 5 ocurrencias dentro de la literatura poética y sapiencial. ''Banda de malhechores me ha rodeado'' (Sal 22:16); ''asamblea de violentos ha buscado mi vida'' (Sal 86:14). La compañía de Coré (Nm 26:9; 27:3) sirve de puente entre los sentidos 1 y 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122495, 'spa', 'enjambre de animales', 'Un enjambre de animales, específicamente abejas: uso trasladado que aplica el concepto de colectivo reunido a criaturas en lugar de personas, en 2 ocurrencias. Jueces 14:8 describe a Sansón hallando ''un enjambre de abejas'' en el cadáver del león, mientras que Salmo 68:30 podría referirse a una ''manada de toros''. La estructura semántica subyacente de grupo compacto se mantiene intacta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122512, 'spa', 'Testimonio material', 'Designa un objeto que sirve como testimonio o prueba legal. Aparece exclusivamente en textos de la fuente E o influidos por ella (Génesis 21:30, 31:52, Josué 24:27 dos veces), refiriéndose a objetos tangibles —corderas, montones de piedras, piedras conmemorativas— que atestiguan acuerdos, pactos o demarcaciones territoriales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122513, 'spa', 'El plural ''testimonios'' o ''decretos'', que designa los mandamientos del pacto de ', 'El plural ''testimonios'' o ''decretos'', que designa los mandamientos del pacto de Dios considerados como atestaciones divinas vinculantes para Israel. Aparece de forma abrumadora en el Salmo 119 (16 de 22 casos) y en los resúmenes deuteronómicos (Dt 4:45; 6:17, 20). Se distingue de otros términos de la Torá por su énfasis en el testimonio personal de Dios. El Salmo 99:7 y 132:12 vinculan la obediencia a estos testimonios con la bendición continua del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122520, 'spa', 'Idó (nombre propio)', 'Profeta y cronista cuyas obras — «las visiones del vidente Idó» y «el midrás del profeta Idó» — sirvieron como fuentes históricas para el relato del Cronista sobre Salomón, Roboam y Abías (2 Cr 9:29; 12:15; 13:22). Probablemente la misma figura que el abuelo del profeta Zacarías (Zac 1:1, 7; Esd 5:1; 6:14). Otros personajes llamados Idó incluyen un gobernador salomónico (1 R 4:14), un levita gersonita (1 Cr 6:21) y un jefe sacerdotal postexílico (Neh 12:4, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122524, 'spa', 'testimonio, documento pactual — El testimonio como entidad pactual singular', 'testimonio, documento pactual — El testimonio como entidad pactual singular: las tablas de la Ley que contienen las Diez Palabras, o por metonimia el Arca y el Tabernáculo que las albergan. A lo largo de 44 ocurrencias, se trata predominantemente de vocabulario sacerdotal. Construcciones clave incluyen ''las tablas del testimonio'' (Éx 31:18; 32:15), ''el Arca del testimonio'' y ''el Tabernáculo del testimonio''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122525, 'spa', 'testimonios, decretos divinos — Los testimonios o estipulaciones de Dios en plur', 'testimonios, decretos divinos — Los testimonios o estipulaciones de Dios en plural: sus mandamientos, ordenanzas y requisitos pactuales vistos como directrices vinculantes para obedecer y atesorar. Abarca 15 ocurrencias, concentradas en los Salmos (especialmente Sal 119) y la Historia Deuteronomística. Las traducciones a veces dejan el hebreo sin traducir entre corchetes, lo cual evidencia la dificultad de encontrar un equivalente único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122539, 'spa', 'ornamento, joya', 'Ornamentos fisicos, joyas y galas llevados sobre el cuerpo. Este sentido primario abarca adornos de oro (2 S 1:24), joyeria nupcial en la alegoria profetica (Ez 16:11; 23:40) e incluso los ornamentos que Israel se despojo en el Horeb por duelo (Ex 33:4-6). Jeremias 2:32 pregunta retoricamente si una novia puede olvidar sus atavios, subrayando el vinculo cultural entre ornamento e identidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122548, 'spa', 'plenitud, esplendor vital', 'Sentido abstracto o figurativo: la plenitud, el esplendor vital o el florecimiento de la vida. En el Salmo 103:5, el texto hebreo ha sido leido como ''tu ornamento'', pero la Septuaginta traduce ''tu deseo'' (ten epithymian sou), sugiriendo que el significado subyacente podria ser ''tus anos de plenitud'' o ''tu vitalidad'' en vez de joyas literales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122552, 'spa', 'Nombre propio', 'Tres individuos distintos con este nombre aparecen exclusivamente en los registros genealógicos y administrativos de Crónicas. Las traducciones muestran un tratamiento estándar de nombre propio mediante transliteración. El nombre figura en genealogías simeonitas, listas sacerdotales y registros administrativos davídicos, lo que refleja la amplitud de las genealogías de Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122553, 'spa', 'Adaías (nombre propio)', 'El nombre propio Adaías, llevado por al menos siete personas distintas: el padre de un capitán de Judá bajo Joiada (2 Cr 23:1), el abuelo materno del rey Josías (2 R 22:1), un levita ancestro en la línea de Asaf (1 Cr 6:41), un benjaminita (1 Cr 8:21), un sacerdote en la Jerusalén postexílica (1 Cr 9:12; Neh 11:12) y dos hombres que habían tomado esposas extranjeras (Esd 10:29, 39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122555, 'spa', 'Babilonia voluptuosa personificada', 'Babilonia personificada como mujer voluptuosa en Isaías 47:8, dentro del oráculo de burla del profeta. «Oye ahora esto, oh voluptuosa, que habitas confiadamente»: el adjetivo femenino se convierte en título burlón que resalta la complacencia autoindulgente de Babilonia. El contexto contrasta su vida lujosa con la humillación inminente: será despojada, expuesta, enlutada y esclavizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122556, 'spa', 'Nombre propio postexílico', 'Nombre personal y familiar en la comunidad postexílica. Los «hijos de Adín» figuran en listas censales paralelas (Esdras 2:15 // Nehemías 7:20), con repatriados adicionales bajo Esdras (Esdras 8:6). Un líder llamado Adín selló el pacto en Nehemías 10:16. Su repetición en Esdras-Nehemías indica una familia prominente en la restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122557, 'spa', 'Guerrero rubenita de David', 'Adina hijo de Siza el rubenita, mencionado en 1 Crónicas 11:42 entre los guerreros de élite de David. No solo fue uno de los valientes, sino también líder de treinta rubenitas. El nombre, que significa algo como «delicado» o «refinado», contrasta curiosamente con su papel militar, quizá otorgado en la infancia o reflejo de un linaje familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122558, 'spa', 'Nombre textualmente problemático', 'El problemático «Adino» en 2 Samuel 23:8, donde el texto lee «Adino el eznita» pero los pasajes paralelos sugieren corrupción. BDB y la mayoría de comentaristas recomiendan leer «blandió su lanza» basándose en 1 Crónicas 11:11, que aclara el sentido original: el guerrero alzó su lanza contra ochocientos muertos de una vez. Las versiones griegas muestran confusión temprana, lo que apoya la hipótesis de corrupción textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122559, 'spa', 'Ciudad en la Sefelá', 'Aditaim, ciudad asignada a Judá en Josué 15:36 dentro del distrito de la Sefelá. La terminación dual sugiere un asentamiento doble o un topónimo con morfología dual por razones poco claras. Las versiones griegas lo transcriben como Adiathaeim, Ageththaim y formas similares. El sitio no ha sido identificado con ninguna localidad moderna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122560, 'spa', 'Padre de Safat', 'Adlai, padre de Safat, mencionado en 1 Crónicas 27:29 entre los oficiales administrativos de David. Safat hijo de Adlai supervisaba los rebaños reales que pastaban en los valles. El nombre probablemente contiene un elemento divino, con el posible significado de ''mi justicia'' o ''justicia de Yah'', aunque su derivación exacta permanece incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122561, 'spa', 'Adulam (nombre propio)', 'Nombre propio que designa la ciudad cananea de Adulam en la Sefelá de Judá. Su importancia bíblica gira en torno a la cueva donde David se refugió de Saúl (1 S 22:1), reuniendo a cuatrocientos hombres. La ciudad figura también en las conquistas de Josué (Jos 12:15) y en las fortificaciones de Roboam (2 Cr 11:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122564, 'spa', 'Gentilicio geográfico', 'Las tres apariciones se refieren a Hirá, amigo de Judá en la historia de Tamar. Las traducciones muestran un tratamiento gentilicio directo: ''adulamita'' en español, siguiendo los patrones respectivos de cada lengua para formar designaciones étnicas. La narrativa de Génesis usa tanto la forma definida como la indefinida, introduciendo primero ''un hombre adulamita'' y luego refiriéndose a él como ''el adulamita''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122565, 'spa', 'Gozo en abundancia divina', 'Israel deleitándose en la generosidad divina durante la conquista, según Nehemías 9:25. Tras enumerar los bienes recibidos — ciudades fortificadas, tierra fértil, cisternas, viñedos, olivares — Nehemías dice que ''comieron, se saciaron, engordaron y se deleitaron en tu gran bondad''. El verbo corona la secuencia, pintando un cuadro de placer abundante antes de la posterior infidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122567, 'spa', 'Territorio arameo', 'Las tres ocurrencias se refieren a este territorio arameo en contextos de conquista asiria y comercio internacional. Los textos proféticos presentan a Edén como ejemplo de nación sometida, parte de la jactancia del imperio asirio. El contexto comercial de Ezequiel lo sitúa entre centros mercantiles del Éufrates medio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122568, 'spa', 'Delicias y deleite', 'Las tres ocurrencias abarcan desde el lujo material hasta el deleite espiritual. El pasaje del Salmo es especialmente notable, usando «delicias» para expresar los goces profundos e intangibles de la presencia de Dios. El uso de Jeremías es incisivo: las delicias de una nación se convierten en botín devorado por el conquistador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122571, 'spa', 'Eden (nombre propio)', 'Nombre propio de la region primordial donde Dios planto el jardin para Adan y Eva. Introducido en Genesis 2:8, 10, 15 y referenciado en la narrativa de la expulsion (Gn 3:23-24) y el episodio de Cain (Gn 4:16). Los profetas lo emplean como simil de fertilidad paradisiaca y bendicion divina restaurada (Is 51:3; Ez 36:35; Jl 2:3). Ezequiel amplia la imagen: Eden como ''el jardin de Dios'' adornado con piedras preciosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122575, 'spa', 'tiempo, período, estación', 'Período temporal general o específico: tiempo, estación o duración señalada. En el uso arameo ordinario dentro de Daniel significa ''tiempo'' como lapso indefinido (Dan 2:8 ''estáis tratando de ganar tiempo''; 2:21 ''él cambia los tiempos y las estaciones''; 7:12 ''por una estación y un tiempo''). En contextos profético-apocalípticos funciona como unidad anual: ''siete tiempos'' equivale a siete años de la locura bestial de Nabucodonosor (Dan 4:13, 20, 22, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122584, 'spa', 'Ciudad del sur de Judá', 'Adadá aparece entre las ciudades del sur de Judá en Josué 15:22, aunque la crítica textual sugiere enmendar a ''Aroer'' (o ''Arará'') basándose en la Septuaginta y listas paralelas de ciudades. BDB señala que la forma podría ser una corrupción de la más conocida Aroer del sur de Judá mencionada en 1 Samuel 30:28. La incertidumbre refleja las dificultades de reconstruir la toponimia antigua a partir de tradiciones manuscritas variantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122585, 'spa', 'Sobrar, estar de más', 'Participio Qal usado como sustantivo para lo que sobra o excede. Abarca el material sobrante de las cortinas del tabernáculo (Éx 26:12-13), el maná restante (Éx 16:23), el excedente en el precio de rescate de un campo (Lv 25:27) y los primogénitos de Israel que superaban en número a los levitas (Nm 3:46, 48-49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122590, 'spa', 'Tener exceso (Hifil)', 'Única forma Hifil, en Éxodo 16:18, que significa ''tener un excedente, haber recogido de más''. A diferencia de las descripciones participiales del sobrante como estado, esta forma capta el resultado activo de la recolección: ''el que recogió mucho no tuvo exceso (הֶעְדִּיף)''. Contrasta deliberadamente con su antónimo הֶחְסִיר (''tuvo de menos''), subrayando la igualación milagrosa del maná.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122591, 'spa', 'Ayudar o asistir', 'El infinitivo ''para ayudar'' en 1 Crónicas 12:34 (o v. 33 según la versificación), aunque muchos eruditos enmiendan a ''para disponer [en batalla]'' basándose en versículos paralelos y contexto. Si la lectura aramea es original, significa ''asistir'' o ''ayudar'', tomada del uso siríaco y targúmico. La frase describe guerreros que vinieron ''para ayudar'' o ''para formar en batalla''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122593, 'spa', 'Faltar, estar ausente', 'Estar ausente, faltar o no encontrarse, generalmente negado para resaltar completitud. En 1 S 30:19 David recupera todo y «nada faltaba» (לֹא נֶעְדַּר); en 2 S 17:22 «no faltó ni uno» que no hubiera cruzado el Jordán. Is 40:26 lo eleva al plano cósmico: Dios convoca a cada estrella y «ninguna falta».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122600, 'spa', 'Benjamita en genealogías', 'Eder el benjamita, mencionado en 1 Crónicas 8:15 dentro de las genealogías de Benjamín. El nombre, idéntico al sustantivo común que significa ''rebaño'', podría reflejar un trasfondo pastoral de la familia o simplemente una tradición onomástica vinculada a la ganadería. Los manuscritos griegos lo transcriben como Ωδηδ, Ωδερ o Αδαρ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122601, 'spa', 'Grupo de animales domésticos — principalmente ovejas y cabras, ocasionalmente va', 'Grupo de animales domésticos — principalmente ovejas y cabras, ocasionalmente vacuno — mantenidos y apacentados juntos. Usado literalmente para el sustento pastoral (Gn 29:2-3, 8; 30:40; 1 S 17:34; Pr 27:23) y en lenguaje figurado que compara a las personas con rebaños bajo el cuidado de un pastor (Is 40:11; Ez 34:12; Mi 5:7). Aparece frecuentemente en estado constructo: עֵדֶר צֹאן (''rebaño de ovejas'', Gn 29:2; Jl 1:18). El Cantar de los Cantares lo emplea poéticamente comparando el cabello de la amada con ''un rebaño de cabras'' (4:1; 6:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122622, 'spa', 'Ciudad del sur', 'La ciudad de Eder en el extremo sur de Judá, mencionada en Josué 15:21 cerca de la frontera con Edom. El nombre, que significa ''rebaño'', sugiere una zona de pastoreo. Su ubicación no ha sido identificada con certeza. Las versiones griegas la transcriben como Αρα, Εδραι o Εβερ, evidenciando una temprana incertidumbre sobre la vocalización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122624, 'spa', 'Legumbre comestible', 'Planta leguminosa y sus semillas comestibles, usadas como alimento. La referencia más célebre es Génesis 25:34, donde Esaú intercambia su primogenitura por un guiso de lentejas. 2 Samuel 17:28 y 23:11 atestiguan las lentejas como cultivo de campo y fuente alimenticia, y Ezequiel 4:9 las incorpora en el pan de asedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122625, 'spa', 'Nublar en juicio', 'El oscurecimiento divino de Jerusalén como acto de juicio, expresado en Lamentaciones 2:1: ''¡Cómo ha nublado el Señor a la hija de Sión en su ira!'' El verbo representa la ira de Dios como una nube densa que cubre la ciudad, ocultando su gloria. La imagen de la nube evoca la presencia divina del Sinaí, ahora vuelta hostil, y la oscuridad del desastre eclipsando el esplendor pasado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122626, 'spa', 'Obed (nombre propio)', 'Nombre propio que significa «adorador» o «el que sirve», aplicado a varios individuos. El más significativo teológicamente es el hijo de Booz y Rut, nombrado por las mujeres del vecindario (Rt 4:17) y situado en la genealogía davídica como padre de Jesé (Rt 4:21-22; 1 Cr 2:12). Otros portadores incluyen un descendiente de Judá por línea de Jerameel (1 Cr 2:37-38), uno de los valientes de David (1 Cr 11:47) y un portero del templo (1 Cr 26:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122628, 'spa', 'Tribu joctanita', 'Obal, descendiente de Joctán en Génesis 10:28, que representa una de las tribus joctanitas de Arabia. El nombre aparece también como Ebal en 1 Crónicas 1:22, reflejando variantes vocálicas en la tradición textual. Los geógrafos antiguos intentaron localizar a sus descendientes en el sur de Arabia, pero la identificación precisa sigue siendo esquiva. El nombre sitúa a este grupo entre los pueblos arábigos con linaje semítico a través de Éber.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122629, 'spa', 'Hornear tortas', 'El horneado de tortas de pan en Ezequiel 4:12, donde Dios ordena al profeta realizar un acto simbólico del exilio venidero: ''La cocerás como torta de cebada, y la cocerás sobre estiércol humano, a vista de ellos.'' El verbo, derivado del sustantivo para ''torta redonda'', enfatiza el proceso de formar y cocer el pan, aquí hecho ritualmente impuro para simbolizar la contaminación del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122630, 'spa', 'El nombre propio Og, que identifica al rey gigante de Basán derrotado por Israel', 'El nombre propio Og, que identifica al rey gigante de Basán derrotado por Israel en Edrei (Nm 21:33). Emparejado formulaicamente con Sijón en las rememoraciones de la conquista transjordana a lo largo de Deuteronomio, Josué, Salmos y Nehemías. Su enorme tamaño queda evidenciado por su cama de hierro (Dt 3:11). Algunos eruditos relacionan el nombre con un epíteto divino original. La Septuaginta lo transcribe como Og y todas las traducciones modernas conservan el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122633, 'spa', 'Instrumento de viento', 'Instrumento musical de identificación incierta, probablemente de viento, como una flauta, caramillo o siringa. Génesis 4:21 lo empareja con el כִּנּוֹר (lira) en los orígenes de la música humana. Job 21:12 y 30:31 lo sitúan en contextos de celebración y duelo respectivamente, mientras que el Salmo 150:4 lo incorpora en la alabanza del templo. Las glosas multilingües favorecen instrumentos de viento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122634, 'spa', 'Rodear y testificar', 'El campo semántico es complejo y posiblemente refleja múltiples raíces homográficas o un desarrollo polisémico. Las glosas incluyen «rodearon» (Salmo 119:61), «estuvieron firmes» (Salmo 20:8), «sostiene» (Salmo 146:9) y «levanta» (Salmo 147:6). La evidencia multilingüe muestra variación significativa: el francés incluye «témoigner» (testificar), sugiriendo sentidos jurídicos, mientras que el español y el inglés reflejan acciones físicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122635, 'spa', 'Advertir, amonestar, exhortar', 'Advertir, amonestar, exhortar: el uso mas frecuente, una advertencia solemne o amonestacion, a menudo con urgencia profetica. Genesis 43:3 presenta la severa exhortacion de Jose, y Exodo 19:21, 23 registra a Dios ordenando a Moises que advierta al pueblo. El enfasis recae en prevenir la maldad o el desastre mediante un discurso investido de autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122636, 'spa', 'Testificar, dar testimonio', 'Testificar, dar testimonio: testimonio formal o declaracion como testigo, ya sea a favor o en contra de alguien. En 1 Reyes 21:10, 13, falsos testigos testifican contra Nabot; en Job 29:11, el oido que escucho a Job daba testimonio a su favor. Deuteronomio 8:19 combina advertencia con testimonio: ''Testifico contra ti hoy.'' El registro juridico de este sentido queda patente en el contexto de Reyes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122638, 'spa', 'Convocar o llamar como testigo', 'Convocar o llamar como testigo: el acto causativo de convocar o establecer testigos, haciendo que alguien o algo sirva de testimonio. Moises pone por testigos a los cielos y la tierra (Dt 4:26; 30:19; 31:28), y Jeremias convoca testigos humanos para una escritura (Jer 32:10). La fuerza causativa del Hifil se expresa en hacer que otros comparezcan como testigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122669, 'spa', 'otra vez, más', 'Adverbio repetitivo o aditivo: ''otra vez, de nuevo, más, además''. Gn 8:21 (''nunca más maldeciré la tierra'') y Gn 9:11 (''nunca más será destruida toda carne'') muestran la partícula en negación jurada de repetición futura. El eje semántico oscila entre recurrencia y acumulación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122670, 'spa', 'todavía, aún', 'Adverbio continuativo: ''todavía, aún'', indicando un estado que persiste. Gn 7:4 (''dentro de siete días más'') y Gn 29:7 (''aún es pleno día'') ilustran la continuación temporal, mientras las formas con sufijo (''odenu, ''mientras él aún'') crean cláusulas compactas de simultaneidad como en Gn 18:22.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122673, 'spa', 'otro, ningún otro', 'Uso sustantivado o adjetival que significa ''otro, ningún otro'', especialmente en declaraciones teológicas de unicidad divina. Dt 4:35 (''no hay otro fuera de él'') e Is 45:5 (''fuera de mí no hay Dios'') emplean ''od para negar la existencia de cualquier deidad rival, desplazando el alcance de lo temporal a lo existencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122675, 'spa', 'mientras aún (temporal)', 'Adverbio temporal con la preposición בְּ: ''mientras aún, mientras todavía'', formando una cláusula subordinada temporal. Gn 25:6 (''mientras Abraham aún vivía'') y Gn 48:7 (''cuando aún faltaba un trecho para Efrata'') anclan esta construcción preposicional en la narrativa de situación temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122694, 'spa', 'continuamente, sin cesar', 'Sentido raro, posiblemente ''continuamente'' o ''sin cesar'', atestiguado una vez en Sal 84:5 donde quienes moran en la casa de Dios ''aún te alaban''. Sugiere una duración ininterrumpida más que repetición: una intensificación litúrgica del significado continuativo básico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122711, 'spa', 'desde mi existencia', 'Con la preposición מִן, expresando ''desde mi existencia, desde siempre''. Solo dos ocurrencias: Gn 48:15 (''el Dios que me ha pastoreado desde mi existencia'') y Nm 22:30 (''la asna sobre la que has cabalgado desde siempre''). Las formas con sufijo comprimen toda una extensión biográfica en una sola frase preposicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122725, 'spa', 'Marcador de inmediatez', 'El marcador de simultaneidad ''aún'' en Daniel 4:31, donde el texto dice: ''Aún estaba la palabra en la boca del rey, cuando una voz cayó del cielo.'' Nabucodonosor estaba alardeando de sus logros cuando, a mitad de frase, el juicio divino lo alcanzó. El adverbio arameo enfatiza la superposición temporal: sus palabras orgullosas no habían concluido cuando llegó la respuesta de Dios, subrayando la rapidez de la retribución divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122726, 'spa', 'Profeta en Crónicas', 'Dos individuos en Crónicas, ambos vinculados al ministerio profético. Los dos Oded aparecen en contextos de reforma religiosa y fidelidad al pacto: uno inspirando las reformas de Asá, y el otro exigiendo misericordia para los cautivos de guerra. La Septuaginta varía en su transcripción, reflejando cierta complejidad textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122727, 'spa', 'Pervertir, torcer (causativo)', 'Formas causativas (Hifil y Piel) que denotan la perversión activa de lo recto, ya sean caminos, superficies o normas morales. En Job 33:27 Elihú confiesa «lo recto yo lo torcí» (הֶעֱוֵיתִי); en Jer 3:21 Israel «torció su camino»; Is 24:1 describe a Dios trastornando la superficie terrestre; Lm 3:9 dice «mis sendas hizo tortuosas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122728, 'spa', 'Estar encorvado, torcido', 'Formas Nifal (pasivas/estativas) que expresan el estado de estar encorvado, doblado o moralmente torcido. En Sal 38:6 el salmista lamenta «estoy encorvado, muy abatido» (נַעֲוֵיתִי, paralelo a שַׁח); Pr 12:8 advierte que el «torcido de corazón» (נַעֲוֵה לֵב) será despreciado; Is 21:3 describe una angustia que deja al profeta «encorvado».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122734, 'spa', 'Cometer iniquidad (Qal)', 'El sentido básico del Qal de obrar mal o cometer una ofensa. Ester 1:16 lo aplica a la negativa de la reina Vasti: «ha ofendido» al rey y a los príncipes, mientras que Daniel 9:5 lo sitúa en la clásica tríada penitencial junto a «pecamos» y «actuamos perversamente». El español «ofendió» para el caso de Vasti capta la ofensa interpersonal, mientras que «cometimos iniquidad» en Daniel preserva el peso confesional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122735, 'spa', 'Actuar perversamente (Hifil)', 'El sentido factitivo del Hifil de actuar perversamente o cometer iniquidad de forma deliberada, la forma más frecuente. La raíz causativa transmite una distorsión moral voluntaria: elegir torcer lo recto. Se encuentra en la confesión de David tras el censo (2 S 24:17), la advertencia condicional de Dios sobre el heredero de Salomón (2 S 7:14), la súplica de David a Simei (2 S 19:19) y las grandes fórmulas confesionales de 1 R 8:47 y Dn 9:5.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122736, 'spa', 'Ser pervertido (Nifal)', 'El sentido participial del Nifal de hallarse en un estado de perversión o torcedura moral. Atestiguado únicamente en el amargo arrebato de Saúl contra Jonatán: «hijo de una mujer perversa y rebelde» (1 S 20:30). El español traduce «perversa», reflejando una condición moral asentada más que un acto puntual de maldad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122744, 'spa', 'Ruina enfática', 'Las tres ocurrencias corresponden a la misma triple repetición de Ezequiel 21:27, una declaración profética enfática sobre la ruina venidera de Jerusalén. Los traductores manejan esta repetición de diversas formas: algunos conservan las tres instancias, otros condensan. El español mantiene el triple «ruina», preservando la fuerza retórica del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122745, 'spa', 'Ciudad asiria conquistada', 'Nombre propio geográfico que designa una ciudad conquistada por Asiria. Aparece en los discursos de propaganda asiria (2 Reyes 18:34, 19:13 // Isaías 37:13) y en el relato del reasentamiento extranjero en Samaria (2 Reyes 17:24, donde la forma es Ava). Las transliteraciones varían: Iva/Ivá/Ava. Las versiones griegas incluyen Αια(ν), Ανα, Ουδου. La ubicación es incierta pero posiblemente en el norte de Siria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122746, 'spa', 'Refugiarse o poner a salvo', 'Buscar o proporcionar refugio y seguridad. El Qal (Isaías 30:2) significa «refugiarse», mientras que el Hifil significa «poner a salvo» (Éxodo 9:19) o «huir/refugiarse» (Isaías 10:31, Jeremías 4:6, 6:1). Las glosas multilingües lo traducen como «huir/refugiarse/poner a salvo». Varias traducciones registran formas entre corchetes como [הָעִזּוּ] y [הָעִיזוּ]. El verbo es fundamentalmente de movimiento protector.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122748, 'spa', 'Iniquidades de Nabucodonosor', 'Las iniquidades de Nabucodonosor en Daniel 4:27, donde Daniel exhorta al rey: «Rompe con tus pecados practicando la justicia, y con tus iniquidades mostrando misericordia a los oprimidos». El plural arameo con sufijo («tus iniquidades») se complementa con «tus pecados» en la cláusula anterior, subrayando la culpa moral acumulada que demanda arrepentimiento. Daniel ofrece un camino para evitar el juicio mediante la justicia y la compasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122750, 'spa', 'Persona injusta', 'La persona injusta o perversa a quien Job se siente entregado en Job 16:11: «Dios me ha entregado al injusto y me ha arrojado en manos de los impíos». El sustantivo destaca la torcedura moral y la injusticia: Job se percibe abandonado a quienes pervierten la rectitud. El término puede ser un singular colectivo que representa una clase o referirse a adversarios específicos que Job ve como agentes de su sufrimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122752, 'spa', 'Ciudad real edomita', 'Las tres ocurrencias se refieren a esta ciudad real edomita. Génesis 36 ofrece la referencia principal, y 1 Crónicas la conserva en paralelo con variación textual entre las lecturas Ketiv y Qeré. La ciudad funciona en la genealogía bíblica como marcador de la legitimidad política de Edom anterior a la monarquía israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122753, 'spa', 'Amamantar, criar', 'Dar de mamar, criar a las crías: usado de las vacas que llevaban el arca (1 S 6:7, 10) y de las ovejas apacentadas por David (Sal 78:71). En Génesis 33:13 Jacob teme que forzar la marcha de los animales lactantes los mate. Isaías 40:11 extiende la imagen: Dios guiará con delicadeza a las que amamantan, metáfora de su cuidado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122754, 'spa', 'Niño lactante', 'Tres apariciones que retratan la vida humana más joven y vulnerable. Isaías lo emplea dos veces en sentido positivo —amor maternal y bendición escatológica—, mientras que Job lo usa para condenar la maldad. La evidencia multilingüe muestra cierta confusión en las glosas, sugiriendo que algunas instancias pudieron captar la preposición עַל junto al sustantivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122756, 'spa', 'La cualidad moral abstracta de injusticia o iniquidad', 'La cualidad moral abstracta de injusticia o iniquidad: desviación de lo recto, justo y equitativo. Este sentido abrumadoramente dominante (21 de 22 ocurrencias) aparece en contextos legales como Lv 19:15 (''no hagáis injusticia en el juicio'') y Lv 19:35 (''no hagáis injusticia en la medición''), en las advertencias repetidas de Ezequiel sobre el justo que se vuelve a cometer עָוֶל (3:20; 18:24, 26; 33:13-18), y en la declaración teológica de Dt 32:4 de que no hay injusticia en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122764, 'spa', 'Una única ocurrencia en Sal 7', 'Una única ocurrencia en Sal 7:3 donde el contexto sugiere un acto concreto de maldad o iniquidad más que la cualidad abstracta. El salmista protesta: ''si hay עָוֶל en mis manos'', refiriéndose a un acto injusto específico del que pudiera ser acusado. Las traducciones multilingües cambian notablemente aquí: el español emplea ''maldad'' (wickedness), reflejando el matiz de un hecho concreto más que de una disposición moral general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122767, 'spa', 'Injusticia, iniquidad', 'Injusticia, iniquidad: maldad entendida como violacion de la justicia o la rectitud en contextos legales, sociales o del pacto. Este sentido predominante (28 ocurrencias) aparece en declaraciones como ''no hay injusticia en el'' (Sal 92:15) y en exhortaciones a abandonar la maldad (Job 11:14; 2 Cr 19:7). El enfasis recae en la dimension relacional y judicial: la falta de equidad en el trato con los demas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122769, 'spa', 'Maldad, perversidad moral', 'Maldad, perversidad moral: maldad o depravacion moral que enfatiza el caracter torcido del malhechor mas que un acto especifico de injusticia. La expresion ''hijos de maldad'' (2 Sam 3:34; 7:10; 1 Cr 17:9; Sal 89:22) senala a personas definidas por su naturaleza corrupta. El matiz semantico apunta a una torcedura moral innata mas que a una injusticia circunstancial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122781, 'spa', 'Injusto, opresor', 'Persona injusta o inicua, especialmente una figura opresora que pervierte la justicia, frecuentemente en paralelo con רָשָׁע en Job (27:7; 31:3). En Sofonías 3:5 el término caracteriza a un gobernante que no conoce la vergüenza, contrastado con la justicia perfecta de Dios. El campo semántico abarca desde la maldad general hasta la injusticia específica y deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122782, 'spa', 'Infante, nio pequeo -- nio muy pequeo o lactante, que designa a bebs y nios pequ', 'Infante, nio pequeo -- nio muy pequeo o lactante, que designa a bebs y nios pequeos completamente dependientes y vulnerables. Frecuentemente emparejado con yoneq (''lactante'') en contextos de guerra total y juicio colectivo: la matanza en Nob (1 Sam 22:19), las atrocidades de Hazael (2 Re 8:12), la cada de Samaria (Os 14:1), la destruccin de Nnive (Nah 3:10) y el dolor crudo del Salmo 137:9. Tambin se usa positivamente en el Salmo 8:2 sobre la alabanza de los nios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122797, 'spa', 'para siempre, eternamente', 'Perpetuidad prospectiva: ''para siempre, por toda la eternidad''. El sentido más frecuente con 280 ocurrencias, generalmente en la frase preposicional le''olam (''para/por la eternidad''). Es el olam del reinado eterno de Dios (Éx 15:18), de la relación perpetua de Israel con Yahvé (Éx 3:15) y del juramento solemne ''tú eres sacerdote para siempre'' (Sal 110:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122799, 'spa', 'perpetuo (atributivo general)', 'Uso adjetival o atributivo: ''eterno, perpetuo'', que califica un sustantivo con sentido de permanencia duradera. Con 98 ocurrencias, modifica pactos (berit olam, Gn 9:16; 17:7), estatutos (juqqat olam, Éx 29:28), posesiones (ajuzzat olam, Gn 17:8) y sacerdocios (kehunnat olam, Éx 40:15). El paso del adverbio ''para siempre'' al adjetivo ''perpetuo'' se marca translingüísticamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122801, 'spa', 'antigüedad, tiempos remotos', 'Antigüedad acotada: ''tiempos antiguos, desde antiguo, antaño''. Con 35 ocurrencias, no refiere a una eternidad pasada infinita sino a una antigüedad histórica dentro de la memoria o tradición nacional. Los ''días de antaño'' (Is 63:9; Am 9:11), las ''sendas antiguas'' (Jr 6:16) y los ''hombres de antaño'' (Gn 6:4) señalan un pasado remoto pero delimitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122802, 'spa', 'desde la eternidad', 'Eternidad dirigida al pasado: ''desde la eternidad, desde antes del tiempo''. Con 17 ocurrencias y la preposición min (''desde''), describe típicamente la autoexistencia eterna de Dios sin principio. La fórmula doxológica ''desde la eternidad y hasta la eternidad'' (1 Cr 16:36; Sal 90:2) enmarca el ser divino como ilimitado en ambas direcciones temporales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122811, 'spa', 'era(s), siglo(s)', 'Eras, siglos o períodos prolongados discretos, a menudo en el plural olamim. Con 8 ocurrencias, estas apariciones resaltan la idea de generaciones o épocas sucesivas en lugar de eternidad indiferenciada. Dt 32:7 exhorta ''acuérdate de los días de antaño, considerad los años de generación en generación'', donde olam se equipara con ''generaciones'' más que con ''eternidad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122849, 'spa', 'Nombre propio', 'Olam, uno de los israelitas que se habían casado con mujeres extranjeras según Esdras 10:2 y su contexto. El nombre, idéntico a la palabra que significa «eternidad» o «perpetuidad», se empleaba como nombre personal en la comunidad postexílica. Fue identificado durante la reforma de Esdras, que exigía la separación de las esposas extranjeras para preservar la pureza del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122850, 'spa', 'Mirada celosa', 'La vigilancia celosa de Saúl sobre David en 1 Samuel 18:9, después de oír cantar a las mujeres: «Saúl mató a sus miles, y David a sus diez miles». El texto dice que Saúl «miraba con recelo a David desde aquel día»: el verbo denominativo retrata la mirada suspicaz y envidiosa del rey fija en su rival. La variación Qeré/Ketiv refleja incertidumbre textual, pero todas las tradiciones preservan el sentido de escrutinio hostil impulsado por los celos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122851, 'spa', 'iniquidad, pecado', 'El acto inicuo en sí: perversidad moral, torcedura, transgresión contra la norma de Dios. Es el sentido dominante con 222 ocurrencias, presente en todos los géneros desde la Torá hasta la literatura sapiencial. En Éx 20:5 Dios ''visita la iniquidad de los padres sobre los hijos'', y en Is 53:6 el Señor ''cargó sobre él la iniquidad de todos nosotros''. La idea raíz es la de torcedura o desviación del camino recto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122868, 'spa', 'culpa, responsabilidad', 'El estado de culpa objetiva o responsabilidad ante Dios: la carga jurídica que se adhiere al pecador. En 2 S 14:9 la mujer sabia dice ''que la culpa recaiga sobre mí y sobre la casa de mi padre'', refiriéndose a la responsabilidad legal, no al acto ni al castigo. Los contextos de transferencia de culpa (1 S 25:24; 2 S 14:32) confirman esta capa semántica distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122877, 'spa', 'castigo, consecuencia', 'El castigo o pena que recae sobre el pecador como consecuencia de su avon. El clamor de Caín en Gn 4:13 —''mi avon es demasiado grande para soportarlo''— se lee clásicamente como ''mi castigo es demasiado grande'', y el contexto de 2 R 7:9 (''la iniquidad nos alcanzará'') apunta a la retribución más que al acto en sí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122907, 'spa', 'colisión homográfica (mirar)', 'Cuestión de crítica textual: en 1 S 18:9 el texto masorético tiene a Saúl ''mirando con recelo'' (עוֹן) a David, pero casi con certeza se trata de una raíz diferente (עין, ''mirar'') y no de avon (''iniquidad''). Esta ocurrencia se explica mejor como una colisión homográfica que como un sentido genuino de avon.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122932, 'spa', 'colisión homográfica (aflicción)', 'Otro caso de crítica textual: en 2 S 16:12, muchos manuscritos leen be''onyi (''mi aflicción'') de una raíz distinta (ענה/עני), no avon. El Qere y varias versiones antiguas apoyan ''aflicción'' en lugar de ''iniquidad''. Como el sentido 4, se trata de un problema escribal u homográfico más que de una extensión semántica genuina de avon.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122945, 'spa', 'Derechos conyugales', 'Aparece en Éxodo 21:10 dentro de las regulaciones del Código de la Alianza sobre el trato a una sierva que se convierte en esposa. Las traducciones multilingües lo interpretan consistentemente como «derechos maritales» o «derechos conyugales», reflejando que se trata de un derecho protegido dentro del pacto matrimonial, no de una mera preferencia. El contexto lo sitúa junto al alimento y la vestimenta como provisiones innegociables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122946, 'spa', 'Distorsión del juicio', 'En Isaías 19:14 describe la confusión espiritual que afligirá al liderazgo de Egipto. El español ''perversidad'' capta el sentido de juicio distorsionado. El contexto sugiere un juicio divino que provoca que los líderes tomen decisiones desastrosas, como si su brújula mental hubiera sido deliberadamente desviada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122947, 'spa', 'Volar (Qal)', 'Volar (Qal): vuelo fisico basico, movimiento aereo de aves, criaturas aladas o sujetos metaforicos. El rollo volador de Zac 5:1 y el vuelo errante del gorrion en Pr 26:2 ejemplifican el uso literal. Sal 18:10 presenta a Dios remontandose sobre alas de querubin, extendiendo la imagen a la teofania.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122948, 'spa', 'Serpiente voladora (Polel participio)', 'Serpiente voladora (Polel participio): la ''serpiente voladora'' (saraf me''ofef) de Is 14:29 y 30:6, criatura mitologica o zoologica del desierto del Neguev. Estas dos ocurrencias combinan la imagen del vuelo con el motivo de la serpiente peligrosa, exclusivo de los oraculos de Isaias contra Filistea y Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122949, 'spa', 'Desfallecer, agotarse (Qal)', 'Desfallecer, agotarse (Qal): una raiz homonima distinta que significa desfallecer o quedar exhausto, presente en relatos de batalla. Jue 4:21 describe a Sisara en profundo agotamiento; 1 Sam 14:28, 31 muestra a las tropas de Jonatan desfalleciendo de hambre. El abismo semantico respecto al sentido 1 sugiere un origen etimologico diferente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122954, 'spa', 'Hacer volar (Hifil)', 'Hacer volar (Hifil): causativo: hacer que los ojos ''vuelen'' hacia las riquezas (Pr 23:5), es decir, fijar la atencion ansiosa en una fortuna que echara alas y se desvanecera. Ambas ocurrencias aparecen en el mismo versiculo, creando un juego de palabras entre poner los ojos y ver como la riqueza emprende el vuelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122958, 'spa', 'Revolotear, aletear (Piel)', 'Revolotear, aletear (Piel): vuelo intensivo, sostenido o repetido, como las criaturas que vuelan sobre el firmamento (Gn 1:20) y los serafines que revolotean sobre el trono divino (Is 6:2). La intensificacion del Piel sugiere un vuelo agitado y revoloteante, no una trayectoria unica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122962, 'spa', 'Blandir (Polel)', 'Blandir (Polel): uso unico en Ez 32:10: ''cuando yo blanda mi espada delante de ellos.'' El movimiento aereo de la raiz se transfiere al arco de una espada en movimiento. El infinitivo constructo be''offefi muestra la metafora del vuelo aplicada al armamento, una extension semantica singular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122969, 'spa', 'Desvanecerse volando (Hitpolel)', 'Desvanecerse volando (Hitpolel): en Os 9:11, la gloria de Efrain ''volara'' como un ave, metafora de la partida subita e irreversible del honor nacional. El tema reflexivo-intensivo subraya la totalidad de la perdida, distinguiendolo del vuelo simple del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122974, 'spa', 'Oscuridad profunda', 'Job 11:17 contrasta el brillo de una vida restaurada (como el mediodía) con este término, que significa ''oscuridad'' o ''tiniebla'' en paralelo con ''mañana''. Las versiones en español e inglés lo traducen como ''oscuridad'', sugiriendo un tiempo de penumbra que será transformado en amanecer, de la desesperanza a la esperanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122975, 'spa', 'ave, pájaro — Aves o pájaros como clase zoológica', 'ave, pájaro — Aves o pájaros como clase zoológica: la designación colectiva para criaturas aviares de toda especie, incluyendo aves del cielo en el marco de la creación (Gn 1:20-22, 26, 28), aves carroñeras que devoran a los muertos (1 S 17:44; 1 R 14:11), aves de los montes (Sal 50:11), aves migratorias (Is 16:2), aves como alimento (Lv 7:26; 17:13) y aves para sacrificio (Gn 8:20; Lv 1:14). Con 67 ocurrencias, es el sentido abrumadoramente dominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (122980, 'spa', 'criatura voladora, ser alado — Criatura voladora en el sentido más amplio, que s', 'criatura voladora, ser alado — Criatura voladora en el sentido más amplio, que se extiende más allá de las aves para abarcar insectos alados: criaturas que vuelan pero ''andan sobre cuatro patas''. Restringido a solo 4 ocurrencias en la legislación dietética levítica (Lv 11:20, 21, 23; Dt 14:19), este sentido es la categoría zoológica más amplia que las leyes de pureza requieren: ''toda criatura voladora que se arrastra sobre cuatro patas os será abominación''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123002, 'spa', 'Plomo (metal)', 'El metal plomo, apreciado en la antigüedad por su peso, maleabilidad y bajo punto de fusión. Se menciona literalmente en listas de metales fundidos (Nm 31:22; Ez 22:18, 20), como producto comercial de Tarsis (Ez 27:12) y como material para rellenar inscripciones grabadas (Job 19:24). La visión de Zacarías emplea un disco de plomo como cubierta del efa (Zac 5:7-8). Su uso figurativo más vívido es en Éxodo 15:10, donde los enemigos se hunden ''como plomo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123010, 'spa', 'Uz (nombre propio)', 'Nombre propio usado tanto para personas en genealogías patriarcales como para la región oriental asociada con Job. Tres figuras genealógicas llevan este nombre: un hijo de Aram (Gn 10:23), un hijo de Nacor (Gn 22:21) y un descendiente horita (Gn 36:28), reflejando la convergencia de tradiciones arameas, abrahámicas y edomitas en el oriente transjordano. Como término geográfico, ''la tierra de Uz'' es la patria de Job y un territorio bajo juicio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123015, 'spa', 'Qal', 'Qal: despertar, estar despierto — Qal intransitivo: despertar, estar despierto, levantarse del sueño — 18 ocurrencias centradas en la propia transición del sujeto del sueño o la inactividad al estado de alerta. El cuádruple ''¡despierta, despierta!'' de Débora (Jue 5:12) es el caso paradigmático, y la autodescripción de la amada ''yo duermo, pero mi corazón vela'' (Cnt 5:2) juega con el límite entre lo literal y lo figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123016, 'spa', 'Hifil', 'Hifil: despertar, avivar (causativo) — Hifil causativo: despertar a alguien, avivar, incitar — el sentido más frecuente con 38 ocurrencias. Dios es el agente típico, avivando el espíritu de reyes (2 Cr 36:22; Esd 1:1), levantando naciones para juicio (Jer 6:22; 50:41) o despertando un instinto protector como el águila que revuelve su nido (Dt 32:11). Alemán erwecken y árabe yuqizu seleccionan vocabulario causativo dedicado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123020, 'spa', 'blandir, empuñar (un arma) — Un sentido marcial especializado', 'blandir, empuñar (un arma) — Un sentido marcial especializado: blandir o empuñar un arma — 3 ocurrencias exclusivamente en las listas de guerreros de 2 Samuel 23:18 y 1 Crónicas 11:11, 20, describiendo a hombres valientes que ''blandieron'' sus lanzas. La acción cinestésica de levantar y blandir apunta a un sentido distinto, no meramente metafórico de despertar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123026, 'spa', 'Piel', 'Piel: avivar, excitar, despertar — Piel intensivo: avivar, excitar, despertar con fuerza deliberada — 11 ocurrencias donde la acción lleva intencionalidad o carga emocional intensificada. La adjuración del Cantar de los Cantares ''no despertéis ni excitéis el amor hasta que quiera'' (Cnt 2:7; 3:5; 8:4) usa esta forma para transmitir la peligrosa volatilidad del despertar prematuro. Proverbios 10:12 advierte que ''el odio despierta contiendas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123027, 'spa', 'Nifal', 'Nifal: ser despertado, ser avivado — Nifal pasivo: ser despertado, ser avivado por una fuerza externa — 7 ocurrencias que enfatizan que el sujeto es receptor y no agente del despertar. Los muertos ''no despertarán'' ni ''serán movidos de su sueño'' (Job 14:12); una gran nación ''se levanta de los confines de la tierra'' (Jer 6:22; 50:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123044, 'spa', 'Hitpael', 'Hitpael: avivarse a sí mismo — Hitpael reflexivo: avivarse, animarse a la acción — 3 ocurrencias donde el sujeto deliberadamente reúne resolución interior. En Is 64:7 el profeta lamenta que nadie ''se anima'' a aferrarse a Dios; Job 17:8 promete que el justo ''se levantará'' contra el impío; Job 31:29 describe el regocijarse cuando llega la desgracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123065, 'spa', 'Desenvainado para batalla', 'Habacuc 3:9 presenta el arco de YHWH completamente expuesto y listo para el combate en una imagen teofánica. El contexto es de guerra santa: las armas de Dios ya no están enfundadas sino plenamente preparadas para ejecutar juicio. El español ''se despierta'' refleja la idea de ser activado o puesto en disposición de combate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123066, 'spa', 'Tamo de la trilla', 'Daniel 2:35 emplea este término en un símil: los pedazos de la estatua ''se hicieron como tamo de las eras de verano'', enfatizando la obliteración total. La comparación subraya que los reinos terrenales, por imponentes que sean, se desvanecerán como desecho arrastrado por el viento ante la piedra cortada sin manos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123067, 'spa', 'piel humana', 'La cobertura exterior del cuerpo humano, especialmente en contextos de enfermedad, sufrimiento y descripción física. Con 59 ocurrencias es el sentido dominante; solo Levítico 13 representa más de la mitad, donde el sacerdote examina la piel en busca de signos de tsara''at. El cuerpo atormentado de Job (Job 7:5; 10:11; 19:20, 26) y el valle de huesos secos de Ezequiel que recibe piel (Ez 37:6, 8) completan el cuadro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123068, 'spa', 'pellejo de animal', 'El pellejo o cuero de un animal, ya sea recién retirado durante el sacrificio o aún sobre el animal vivo. Con 27 ocurrencias concentradas en la legislación sacrificial: el ''cuero del novillo'' quemado fuera del campamento (Éx 29:14; Lv 4:11), el derecho sacerdotal al cuero del holocausto (Lv 7:8) y la estratagema de Jacob con pieles de cabrito en sus manos (Gn 27:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123070, 'spa', 'cuero como material', 'Piel de animal procesada como cuero, usada para artículos manufacturados como vestiduras, recipientes y cubiertas del tabernáculo. Con 13 ocurrencias, aparecen principalmente en regulaciones de pureza (Lv 11:32; 13:48-59; 15:17) y en la construcción del tabernáculo (Éx 25:5; 26:14). Las ''pieles de carnero teñidas de rojo'' y las ''pieles de tajash'' muestran el cuero como material trabajado, distinto del pellejo crudo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123090, 'spa', 'Cegar, quitar la vista', 'Hacer ciego, sacar los ojos: literalmente de la ceguera infligida por los babilonios a Sedequías (2 R 25:7; Jer 39:7; 52:11), y figuradamente del soborno que corrompe el discernimiento judicial (Éx 23:8; Dt 16:19). Ambos usos comparten la imagen de la vista destruida, sea por mutilación física o por corrupción moral del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123091, 'spa', 'Incapaz de ver, empleado tanto en sentido literal como figurado', 'Incapaz de ver, empleado tanto en sentido literal como figurado. Literalmente, describe la ceguera física como condición que Dios soberanamente asigna (Éx 4:11), una discapacidad protegida por la Torá (Lv 19:14; Dt 27:18) y una descalificación sacrificial (Dt 15:21; Mal 1:8). Figuradamente, especialmente en Isaías, caracteriza la insensibilidad espiritual: Israel como siervo ciego de Dios (Is 42:19), guardianes ciegos (Is 56:10), y la promesa de que los ojos ciegos serán abiertos (Is 29:18; 35:5; 42:7, 16, 18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123100, 'spa', 'Defecto sacrificial', 'Levítico 22:22 enumera la ''ceguera'' entre los defectos (fractura, mutilación, úlcera, sarna) que hacen inaceptable a un animal para el sacrificio. El código de santidad insiste en que solo ofrendas sin tacha son apropiadas para el altar de YHWH, convirtiendo la ceguera en una condición descalificante para el servicio sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123101, 'spa', 'Apresurarse al juicio', 'Joel 3:11 (en algunas versiones 4:11) convoca a las naciones circundantes a acudir con urgencia, aunque el verbo exacto es disputado. Las traducciones lo vierten como ''apresuraos'', subrayando la urgencia. El contexto es la reunión de las naciones para el juicio en el valle de Josafat, donde Dios ejecutará justicia. Ya sea que el verbo signifique ''ayudar'', ''apresurarse'' o ''congregarse'', el sentido es un llamado dramático a una asamblea veloz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123102, 'spa', 'Sostener con palabras', 'Isaías 50:4 describe la capacidad del Siervo de ''sostener al cansado con una palabra''. El Siervo es presentado como alguien que sabe dar la palabra justa en el momento preciso, fortaleciendo a quienes están agotados, desanimados o a punto de rendirse. Esto encaja con el tema más amplio de los Cantos del Siervo, donde la misión divina incluye consolar y restaurar al abatido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123103, 'spa', 'Torcer, pervertir, subvertir', 'Piel activo: torcer, pervertir o subvertir, especialmente la justicia y el trato recto. La angustiada pregunta de Job — ¿tuerce Dios el mishpat? (Job 8:3) — y la denuncia de Amós contra los mercaderes que falsean las balanzas (Am 8:5) definen este sentido. El español «pervertir» señala una distorsión moral deliberada. También abarca la subversión personal como en Salmo 119:78 y Job 19:6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123107, 'spa', 'Torcido, pervertido (pasivo)', 'Participio pasivo del Pual: aquello que ha sido torcido y no puede enderezarse. Eclesiastés 1:15 emplea esta única ocurrencia para expresar la imposibilidad de corregir lo que está fundamentalmente deformado. El español «lo torcido» capta la cualidad resultativa y estativa de este participio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123110, 'spa', 'Encorvarse, doblarse (reflexivo)', 'Hitpael reflexivo: encorvarse o doblarse, describiendo el deterioro físico. En Eclesiastés 12:3, los «hombres fuertes» (las extremidades del cuerpo) se encorvan con la edad. El español «se encorven» refleja al sujeto reflexivo sufriendo el encorvamiento: un conmovedor giro de la perversión moral al inevitable declive corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123112, 'spa', 'Injusticia sufrida', 'Lamentaciones 3:59 presenta al hablante apelando a YHWH: ''Tú has visto mi agravio'', en paralelo con ''juzga mi causa''. El contexto es un clamor por vindicación: el hablante ha sido agraviado, sus derechos subvertidos, y apela a Dios como juez justo para que vea la injusticia y restablezca lo correcto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123114, 'spa', 'Denota poder físico, militar o abstracto robusto', 'Denota poder físico, militar o abstracto robusto: una nación poderosa, un viento recio del este, aguas demasiado impetuosas para cruzar. La evidencia multilingüe se agrupa estrechamente en torno a ''fuerte/strong/fort'', reflejando potencia directa. Aplicado a pueblos (Nm 13:28), fuerzas naturales (Éx 14:21) e incluso al amor y la muerte (Cnt 8:6), este es el sentido nuclear: fuerza cruda y predominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123116, 'spa', 'Desplaza el significado de la fuerza hacia su faceta amenazante', 'Desplaza el significado de la fuerza hacia su faceta amenazante: fiereza, dureza, severidad. El oráculo mortuorio de Jacob condena la ira de sus hijos como ''feroz'' (Gn 49:7), y Pr 18:23 contrasta las súplicas del pobre con las respuestas ''duras'' del rico. La fuerza se torna cruel o implacable, como refleja el español ''feroz'' y el alemán ''heftig''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123117, 'spa', 'Aparece en construcciones de estado constructo — ''fiero de rostro'' (Dt 28', 'Aparece en construcciones de estado constructo — ''fiero de rostro'' (Dt 28:50; Dn 8:23), ''fuerte de apetito'' (Is 56:11) — para transmitir osadía, insolencia o voracidad. La construcción intensifica una cualidad hasta convertirla en rasgo definitorio: no meramente fuerte, sino descaradamente audaz. El español ''fiera de'' y el alemán ''grimmig'' reflejan este paso de la fuerza general a una agresión o codicia desvergonzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123126, 'spa', 'Aplicación transferida a una ciudad o fortaleza', 'Aplicación transferida a una ciudad o fortaleza: ''Ciudad fuerte tenemos'' (Is 26:1). Aquí el adjetivo pasa de la fuerza personal a la inexpugnabilidad arquitectónica — muros, puertas y protección divina que hacen un lugar inconquistable. Solo una ocurrencia porta este sentido de fortificación, pero conecta naturalmente con el significado nuclear de fuerza abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123131, 'spa', 'cabra(s) hembra — La cabra hembra como animal doméstico criado en rebaños para a', 'cabra(s) hembra — La cabra hembra como animal doméstico criado en rebaños para alimento, patrimonio y sacrificio. Abarca la abrumadora mayoría de las ocurrencias, desde los rebaños de Jacob (Gn 30:33) hasta las víctimas pascuales (Éx 12:5) y las ofrendas levíticas (Lv 22:19, 27). Las traducciones lo rinden uniformemente con términos estándar para cabra: español cabras, francés chèvres, alemán Ziegen, confirmando un núcleo semántico único y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123135, 'spa', 'pelo de cabra (como material) — Pelo de cabra usado como materia prima textil, e', 'pelo de cabra (como material) — Pelo de cabra usado como materia prima textil, especialmente para tejer las cortinas y cubiertas del tabernáculo. Las seis ocurrencias se agrupan en Éxodo 25-35. La evidencia multilingüe es reveladora: español pelo de cabras, francés chèvre cheveux y alemán Ziege-Haar añaden un componente de ''pelo'' ausente del sentido ganadero, marcando una genuina extensión metonímica del animal a su fibra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123149, 'spa', 'Cabras sacrificiales', 'Esdras 6:17 enumera los sacrificios en la dedicación del templo: 100 toros, 200 carneros, 400 corderos y 12 machos cabríos como ofrenda por el pecado. La forma plural aramea refleja el idioma del decreto y la narrativa en esta sección de Esdras. Los 12 machos cabríos corresponden a las 12 tribus, simbolizando la expiación por todo Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123150, 'spa', 'fuerza, poder, potencia — El sentido dominante', 'fuerza, poder, potencia — El sentido dominante: fuerza, poder, potencia en toda su amplitud — omnipotencia divina (''dad a Jehová gloria y poder'', 1 Cr 16:28), autoridad real (''el rey se alegrará en tu poder'', Sal 21:1), vigor físico (2 S 6:14) y fuerza nacional. Los Salmos lo usan más que cualquier otro libro, frecuentemente en paralelismo con כָּבוֹד (''gloria'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123162, 'spa', 'fortaleza, torre fuerte — La fuerza como atributo concreto arquitectónico o prot', 'fortaleza, torre fuerte — La fuerza como atributo concreto arquitectónico o protector: una ''torre fuerte'' (מִגְדַּל עֹז, Jue 9:51) o un ''refugio fuerte'' (מַחֲסִי עֹז, Sal 71:7). Aquí la cualidad abstracta se materializa en imaginería de fortificación: el nombre de Jehová es torre fuerte (Pr 18:10). Este uso tiende un puente entre estructura física y seguridad metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123170, 'spa', 'fortaleza (de Babilonia) — Un uso contextual en Jeremías 51', 'fortaleza (de Babilonia) — Un uso contextual en Jeremías 51:53 donde la palabra aparece en proximidad con la altura fortificada de Babilonia. Algunas traducciones reflejan posible confusión con el topónimo עַזָּה (Gaza), pero el texto hebreo describe la ''fortaleza'' de Babilonia — su alta fortificación — como objeto del juicio divino. La divergencia multilingüe aquí es en sí misma instructiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123178, 'spa', 'dureza, audacia del semblante — La audacia o fuerza del semblante o porte de una', 'dureza, audacia del semblante — La audacia o fuerza del semblante o porte de una persona, como en Eclesiastés 8:1: ''la dureza (עֹז) de su rostro se mudará''. Aquí la fuerza se transfiere del poder físico o militar a la confianza feroz visible en la expresión de una persona. Español dureza y francés force capturan este matiz especializado de reciedumbre en el porte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123193, 'spa', 'Uza / Uzá (nombre propio)', 'Nombre propio que significa ''fuerza'', aplicado a varios individuos: principalmente el hijo de Abinadab, fulminado por tocar el Arca de la Alianza durante su transporte a Jerusalén (2 Sam 6:3–8; 1 Cr 13:7–11). También designa el ''jardín de Uza'' donde fueron sepultados los reyes Manasés y Amón (2 Re 21:18, 26), un descendiente benjaminita (1 Cr 8:7) y un jefe de clan entre los servidores del templo que regresaron del exilio (Esd 2:49; Neh 7:51).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123200, 'spa', 'Levita en genealogías', '1 Crónicas 6:29 (en algunas versiones 6:14) incluye a Uza en la genealogía levítica. Como levita, Uza pertenecía a la tribu apartada para el servicio sagrado. El nombre ''fuerza'' era común en el antiguo Israel y celebraba el vigor humano o el empoderamiento divino. Las variantes de la Septuaginta reflejan distintos intentos griegos de transliterar el nombre hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123201, 'spa', 'Ritual de expiación', 'Término de significado incierto central al rito del chivo expiatorio en Levítico 16:8, 10 (dos veces), 26. Las interpretaciones eruditas van desde un sustantivo abstracto que significa «remoción completa» (intensivo reduplicativo de עזל, remover) hasta un nombre propio de un demonio o espíritu del desierto. La tradición judía posterior desarrolla a Azazel como un ángel caído. Las glosas multilingües transliteran el término de forma consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123202, 'spa', 'abandonar, desamparar', 'El sentido dominante en Qal activo: abandonar, desamparar o desertar voluntariamente. Cubre el abandono del pacto con Dios (Dt 29:25; Jue 2:12-13; 10:6), la deserción de personas y el incumplimiento de mandamientos. Los profetas lo emplean como término de demanda judicial del pacto: Israel ha ''abandonado'' al Señor que lo redimió.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123206, 'spa', 'dejar, dejar atrás', 'Dejar o dejar atrás, sin el peso moral de la traición. En Gn 2:24 un hombre ''deja'' a sus padres para unirse a su esposa; en Gn 39:6 Potifar ''dejó'' todos sus asuntos en manos de José. La diferencia con el sentido 1 es la ausencia de rechazo: lo que se deja atrás no está siendo repudiado sino transferido o puesto en segundo plano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123214, 'spa', 'abandonado, desamparado', 'Uso participial y adjetival que describe a alguien o algo como ''abandonado'' o ''desamparado''. Isaías 62:4 promete a Jerusalén ''no serás llamada más Azuvá (Abandonada)'', mientras textos como 1 R 14:10 y 2 R 14:26 describen la condición desvalida de quienes quedan sin protector.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123216, 'spa', 'ser abandonado (pasivo)', 'Formas finitas en Nifal o Qal pasivo que expresan el evento o estado de ser abandonado. En Lv 26:43 la tierra ''será abandonada'', y en Is 7:16 la tierra cuyos dos reyes Israel teme ''será desamparada''. Sal 37:25 ofrece el célebre testimonio: ''no he visto al justo desamparado'', declaración teológica de la fidelidad protectora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123251, 'spa', 'ayudar con la carga', 'Notable caso semántico aislado: ayudar o asistir, específicamente en aliviar a un animal de su carga (Éx 23:5). Las tres ocurrencias provienen del mismo versículo y su contexto legal circundante. Algunos estudiosos derivan este sentido de una raíz homónima; otros ven una extensión semántica del significado básico de ''dejar'': dejar la carga, es decir, descargar al animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123342, 'spa', 'Restaurar o fortificar', 'Nehemías 3:8 describe la labor de un grupo en la muralla: ''restauraron Jerusalén hasta el Muro Ancho.'' La traducción española ''y dejaron'' refleja una interpretación desde la raíz ''abandonar'', pero resulta contextualmente extraña. ''Restauraron'' se ajusta mejor al tema del capítulo, donde diferentes grupos reconstruyen distintas secciones de la muralla. El sentido exacto sigue siendo incierto, pero la restauración o fortificación es lo más probable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123343, 'spa', 'Mercancías comerciales', 'Bienes o mercancías intercambiados en transacciones comerciales, apareciendo únicamente en el elaborado catálogo de la red comercial de Tiro en Ezequiel 27. En Ez 27:12, Tarsis comerciaba plata, hierro, estaño y plomo ''como tus mercancías''; el v.14 menciona caballos y mulas de Bet-Togarmá; el v.16 cita turquesas, púrpura, bordados y coral de Aram; y el v.19 registra hierro forjado y casia, entre otros productos de lujo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123346, 'spa', 'Nombre propio masculino', 'Nehemías 3:16 identifica a uno de los constructores del muro como ''Nehemías hijo de Azbuc, gobernador de la mitad del distrito de Bet-sur.'' El nombre Azbuc aparece solo aquí, como patronímico que distingue a este Nehemías del gobernador homónimo. Su hijo supervisó las reparaciones frente a los sepulcros de David y la piscina artificial, asumiendo responsabilidad en la restauración del muro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123347, 'spa', 'Nombre personal y familiar', 'Nombre personal y de familia que significa «Gad es poderoso». La familia de Azgad aparece en las listas paralelas del retorno (Esdras 2:12 // Nehemías 7:17) y entre los que regresaron con Esdras (Esdras 8:12). Un Azgad selló el pacto en Nehemías 10:15. Su estructura teofórica (deidad + epíteto) es típica de la onomástica hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123348, 'spa', 'Gaza (ciudad filistea) -- la principal ciudad filistea en la costa meridional de', 'Gaza (ciudad filistea) -- la principal ciudad filistea en la costa meridional del Mediterrneo, una de las cinco ciudades-estado filisteas junto con Asdod, Ascaln, Gat y Ecrn. Marca el lmite suroeste de Canan (Gn 10:19), aparece en las hazaas de Sansn (Jue 16:1, 21), listas de conquista (Jos 10:41; 11:22) y orculos profticos: Ams denuncia a Gaza por deportar comunidades enteras a la esclavitud (Am 1:6-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123351, 'spa', 'Aya (nombre propio) -- topnimo que aparece en 1 Crnicas 7', 'Aya (nombre propio) -- topnimo que aparece en 1 Crnicas 7:28 dentro de la descripcin territorial de la tribu de Efran, distinto de la ciudad filistea. Las glosas multilinges confirman una identidad separada: en espaol se traduce ''Aya'', lo que sugiere que puede tratarse de una lectura variante o un asentamiento diferente. La forma consonantal hebrea coincide con Gaza, pero el contexto geogrfico y tribal apunta a otra localidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123355, 'spa', 'Región desamparada', 'Isaías 6:12 advierte que ''el abandono será grande en medio de la tierra.'' El contexto es la visión de juicio de Isaías: el pueblo será removido lejos y quedará una vasta región desolada en el corazón de la tierra. El participio pasivo subraya el estado resultante del abandono, reflejando el juicio divino sobre una nación que se apartó de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123356, 'spa', 'Nombre personal femenino', 'Nombre personal femenino llevado por dos mujeres bíblicas: (1) la madre de Josafat (1 Reyes 22:42 // 2 Crónicas 20:31) y (2) la esposa de Caleb (1 Crónicas 2:18-19). El nombre probablemente significa «abandonada», quizá reflejando circunstancias del nacimiento. Las versiones griegas lo transcriben como Αζαεβα, Αζονβα o Γαζουβα.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123357, 'spa', 'Fuerza divina', 'Tres apariciones, todas describiendo los actos poderosos de Dios o la fuerza feroz del juicio divino. Los Salmos lo emplean en contextos de adoración y testimonio, recordando las hazañas de Yahvé. El uso en Isaías es más sombrío: la fiereza de la batalla se convierte en instrumento de la ira de Dios. Las glosas multilingües captan la idea central de fuerza, poder y poderío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123359, 'spa', 'Nombre propio', 'Tres individuos distintos, siendo el padre del falso profeta Hananías el más prominente. La evidencia multilingüe muestra transliteraciones estándar con variantes menores (Azur/Azzur) según las convenciones de cada idioma. Jeremías 28 otorga a Azur notoriedad como padre de un profeta que contradijo el mensaje de Jeremías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123360, 'spa', 'Ser fuerte, prevalecer', 'Ser o llegar a ser fuerte, poderoso, prevaleciente — el sentido intransitivo del Qal de una fuerza que se impone. Jueces 3:10 y 6:2 lo emplean para una mano que ''fue fuerte contra'' un enemigo. Salmos 9:19 y 52:7 lo aplican a la rebeldía humana o la fragilidad mortal ante Dios. Proverbios 8:28 describe manantiales que se fortalecen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123362, 'spa', 'Fortalecer, hacer fuerte', 'Fortalecer o hacer fuerte — un sentido transitivo o imperativo que dirige el poder hacia otro. El Salmo 68:28 suplica a Dios que ''fortalezca'' su obra consumada sobre Israel, y Eclesiastés 7:19 observa que la sabiduría ''fortalece'' al sabio más que diez gobernantes. El matiz causativo implica impartir fuerza a otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123366, 'spa', 'Endurecer el rostro', 'Hacer audaz o descarado el rostro (Hifil causativo), expresando impudencia o desafío mediante una expresión facial endurecida. Proverbios 7:13 describe a la seductora que ''endureció su rostro'' antes de besar al joven, y Proverbios 21:29 contrasta al impío que ''endurece su rostro'' con el recto que considera sus caminos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123371, 'spa', 'Nombre propio rubenita', '1 Crónicas 5:8 menciona a Azaz en la genealogía de Rubén: ''Bela hijo de Azaz, hijo de Sema, hijo de Joel.'' Como rubenita, Azaz pertenecía a la tribu asentada al este del Jordán. Su inclusión en la genealogía preserva la memoria tribal incluso después de la caída del reino del norte y el exilio temprano de las tribus transjordanas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123372, 'spa', 'Nombre teofórico', 'Tres individuos en Crónicas, todos en contextos levíticos o administrativos. La evidencia multilingüe muestra patrones de transliteración con variantes según cada versión. Los críticos textuales señalan posible confusión con los nombres similares Uzías y Azarías, ya que las consonantes hebreas se superponen significativamente. El contexto de Crónicas enfatiza el servicio en el templo y la administración religiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123373, 'spa', 'Uzzi (nombre propio)', 'Nombre propio que significa ''mi fuerza'', llevado por múltiples personajes en las genealogías y registros administrativos de Israel. El portador principal es un sacerdote de la línea aarónica de Eleazar (1 Cr 6:5-6, 51; Esd 7:4). Otros Uzzi incluyen un jefe militar isacarita (1 Cr 7:2-3), un benjaminita (1 Cr 7:7; 9:8), un supervisor levítico del culto bajo Nehemías (Neh 11:22) y jefes de familias sacerdotales (Neh 12:19, 42).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123375, 'spa', 'Guerrero valiente davídico', '1 Crónicas 11:44 enumera a ''Uzías el asteratita'' entre los valientes de David, los selectos ''Treinta'' que realizaron hazañas extraordinarias de valor. Como uno de los héroes de David, Uzías representa a los guerreros leales que ayudaron a establecer y defender el reino de David, hombres cuyos nombres fueron preservados en el registro de honor militar de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123376, 'spa', 'Músico levita', '1 Crónicas 15:20 menciona a «Aziel» entre los músicos levitas que tocaban liras, mientras que el versículo 18 lo llama Uziel. El contexto es el segundo intento de David de trasladar el arca a Jerusalén, ahora con los procedimientos levíticos apropiados, incluyendo música y celebración. Aziel/Uziel tocaba en alamot, posiblemente un modo o instrumento musical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123377, 'spa', 'Uziel (nombre propio) -- nombre masculino propio que significa ''mi fortaleza es ', 'Uziel (nombre propio) -- nombre masculino propio que significa ''mi fortaleza es Dios'', identificando principalmente al levita coatita que fund el clan uzielita. La mayora de las ocurrencias trazan este linaje levtico a travs de xodo, Nmeros y Crnicas (x 6:18; Nm 3:19, 30; 1 Cr 23:12, 20). Portadores secundarios incluyen msicos del templo, un capitn simeonita y el constructor de muros de Nehemas (Neh 3:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123380, 'spa', 'El rey de Judá (c', 'El rey de Judá (c. 792-740 a.C.), también conocido como Azarías, cuyo largo y próspero reinado terminó cuando fue herido con lepra por usurpar funciones sacerdotales (2 Cr 26:16-21). Su muerte marca la visión inaugural de Isaías (Is 6:1). Las traducciones multilingües transliteran de forma consistente — ''Uzías'' (spa), ''Ozias'' (fra), ''Usija'' (deu) — mientras que la Septuaginta alterna entre Ozías y Azarías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123386, 'spa', 'El nombre Uzías portado por otros individuos', 'El nombre Uzías portado por otros individuos: un antepasado levita de Hemán el cantor (1 Cr 6:24), el padre de uno de los oficiales de David (1 Cr 27:25), un sacerdote que tomó mujer extranjera tras el exilio (Esd 10:21) y un judío en la Jerusalén postexílica (Neh 11:4). Estos portadores menores aparecen en listas genealógicas y administrativas más que en contextos narrativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123388, 'spa', 'Descendiente de Zatú', 'Esdras 10:27 menciona a Aziza entre los descendientes de Zatú que se habían casado con mujeres extranjeras. El contexto más amplio es la campaña de Esdras para disolver los matrimonios mixtos considerados una amenaza a la lealtad al pacto. Aziza aparece únicamente en esta lista de quienes cumplieron con la orden.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123389, 'spa', 'Azmavet (nombre propio)', 'Nombre propio que designa a varios individuos asociados con la administración de David y genealogías benjaminitas. El nombre combina elementos que significan ''fuerza'' y ''muerte'', sugiriendo fortaleza ante la mortalidad. Identifica a uno de los guerreros de élite de David (2 S 23:31, 1 Cr 11:33), al padre de desertores benjaminitas que se unieron a David (1 Cr 12:3), un supervisor real de los tesoros (1 Cr 27:25) y también una localidad postexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123392, 'spa', 'Padre de Paltiel', 'Números 34:26 identifica a «Paltiel hijo de Azán» como el líder de Isacar designado para ayudar en la distribución de la tierra. El hijo de Azán sirvió junto a Josué y Eleazar en la tarea crucial de la asignación territorial tribal, asegurando que Isacar recibiera su herencia correspondiente en Canaán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123394, 'spa', 'Labrar la tierra', 'Isaías 5:2 describe el cuidado del dueño de la viña: «la cavó con esmero» o «la limpió de piedras», según la interpretación del verbo intensivo. El Cántico de la Viña emplea este verbo para enfatizar que el dueño hizo todo lo posible para asegurar una buena cosecha, haciendo que las uvas silvestres resultantes no fueran culpa suya sino de la viña misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123396, 'spa', 'Azeca (topónimo)', 'La ciudad fortificada de Azeca en la Sefelá de Judá, situada cerca de Soco con vista al valle de Elá. Sirvió como punto militar clave: las fuerzas de Josué persiguieron a los reyes amorreos junto a ella (Jos 10:10-11), los ejércitos de David y Saúl acamparon cerca contra los filisteos (1 S 17:1), y Jeremías la nombra como una de las últimas ciudades de Judá que resistieron a Babilonia (Jer 34:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123399, 'spa', 'participio Qal', 'participio Qal: ayudador — Participio activo del Qal usado sustantivamente: un ayudador, aliado, el que presta ayuda — 21 ocurrencias que funcionan casi como título. En los Salmos Dios es ''mi ayudador'' (Sal 30:10; 54:4); en Crónicas la palabra designa aliados militares y partidarios (1 Cr 12:1, 19). Las lenguas seleccionan sustantivos agentivos de ''ayudador'', confirmando que se trata de un uso sustantivado lexicalizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123400, 'spa', 'Qal', 'Qal: ayudar, auxiliar — Formas finitas del Qal: ayudar, auxiliar o asistir a alguien — el sentido verbal central con 53 ocurrencias. Abarca la asistencia militar (Jos 1:14; 10:4-6, los gabaonitas clamando ''¡subid y ayudadnos!''), la ayuda divina (Gn 49:25; Sal 118:13, ''Jehová me ayudó'') y la ayuda general entre personas. Español ayudar, alemán helfen y coreano 돕다 coinciden sin ambigüedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123416, 'spa', 'Nifal', 'Nifal: ser ayudado — Nifal pasivo: ser ayudado, recibir auxilio — 4 ocurrencias con morfología pasiva consistente en todas las lenguas meta. En 1 Cr 5:20 los rubenitas ''fueron ayudados'' contra los agarenos; en Sal 28:7 el salmista declara ''en él confió mi corazón y fui ayudado''. Daniel 11:34 usa esta forma en el contexto de los macabeos recibiendo ''poca ayuda''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123427, 'spa', 'participio Qal pasivo', 'participio Qal pasivo: el ayudado — Una única ocurrencia del participio Qal pasivo en Is 31:3: ''el ayudado caerá'', donde la forma הָעָזוּר describe al que ha recibido auxilio. Tanto español el ayudado como alemán der Geholfene usan participios pasivos sustantivados, confirmando este uso morfológico distinto: el receptor de ayuda como entidad caracterizada, formando pareja con el ''ayudador'' activo del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123435, 'spa', 'Hifil', 'Hifil: prestar ayuda — Hifil causativo: prestar ayuda, dar asistencia — 3 ocurrencias donde el tema causativo puede intensificar o formalizar el acto de ayudar. En 2 S 18:3 los hombres de David le dicen ''mejor será que tú nos des ayuda desde la ciudad''; en 2 Cr 28:23 Acaz sacrifica a los dioses de Damasco, razonando que ''ellos ayudaron a los reyes de Siria''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123452, 'spa', 'Hijo de Efraín', '1 Crónicas 7:21 menciona a Ezer entre los hijos de Efraín que fueron muertos por hombres de Gat durante una incursión para robar ganado. La genealogía preserva esta tragedia familiar: los hijos de Efraín, Ezer y Elad, fueron a apoderarse del ganado de Gat pero murieron a manos de los habitantes locales, provocando un luto prolongado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123453, 'spa', 'Ayuda, asistencia o socorro abstracto', 'Ayuda, asistencia o socorro abstracto: el acto o la cualidad de dar auxilio. Este sentido dominante (19 ocurrencias) aparece con sufijos posesivos que indican de quién es la ayuda: ''mi ayuda'' (Éx 18:4, donde Moisés nombra a su hijo Eliezer, ''mi Dios es ayuda''), ''tu ayuda'' (Dt 33:29), ''nuestra ayuda'' (Sal 124:8). Los Salmos son especialmente ricos: ''Mi socorro viene del SEÑOR'' (121:1-2), ''Él es nuestra ayuda y nuestro escudo'' (33:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123456, 'spa', 'Un sentido concreto y personal', 'Un sentido concreto y personal: un ayudador, alguien que presta auxilio. Gn 2:18 y 2:20 emplean la construcción beth essentiae be''ezer (''como ayuda'') para la mujer que Dios crea como contraparte del hombre — no una subordinada sino una aliada correspondiente. Dt 33:7 lo aplica a Dios como ayudador de Judá en batalla. La cualidad personal queda confirmada por la evidencia multilingüe: ''helper'' en inglés, ''aide'' en francés y ''ayuda'' en español.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123468, 'spa', 'Nombre personal hebreo', 'Nombre personal que significa «ayuda» o «ayudador», atestiguado tanto en inscripciones fenicias y hebreo antiguo como en textos bíblicos. Tres individuos distintos llevan este nombre: (1) un ancestro judahíta (1 Crónicas 4:4), (2) un guerrero gadita de David (1 Crónicas 12:10) y (3) un líder postexílico (Nehemías 3:19; 12:42).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123469, 'spa', 'El nombre personal Esdras (hebreo עֶזְרָא, ''ayuda''), que identifica principalmen', 'El nombre personal Esdras (hebreo עֶזְרָא, ''ayuda''), que identifica principalmente al sacerdote y escriba que regresó de Babilonia y restauró la observancia de la Torá (Esd 7-10; Neh 8-12). También lo llevan un sacerdote de la generación de Zorobabel (Neh 12:1) y un participante en la dedicación del muro (Neh 12:33). La Septuaginta da Esdras, reflejado en español y francés, mientras que el alemán Esra y el inglés Ezra se acercan más a la forma hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123472, 'spa', 'Esdras el escriba', 'Tres apariciones en Esdras 7:12, 21 y 25, todas dentro del decreto arameo de Artajerjes. La evidencia multilingüe muestra la transliteración estándar del nombre. Lo notable es el tono formal y oficial: se trata de Esdras en documentos imperiales persas, no en narrativa hebrea. El contexto arameo subraya la realidad política que hizo posible las reformas religiosas postexílicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123473, 'spa', 'Azarel (nombre propio)', 'Nombre masculino propio que significa ''Dios ha ayudado'', portado por varios individuos en diferentes períodos. La Septuaginta lo traduce variadamente como Ozriēl y Ezriēl, mientras que en español se alterna entre ''Azareel'' y ''Azarel''. El nombre aparece en contextos militares (1 Cr 12:7), litúrgicos (1 Cr 25:18), administrativo-tribales (1 Cr 27:22), de reforma (Esd 10:41) y sacerdotales (Neh 11:13; 12:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123475, 'spa', 'Ayuda, auxilio o asistencia — predominantemente socorro divino buscado en la cri', 'Ayuda, auxilio o asistencia — predominantemente socorro divino buscado en la crisis. El salmista suplica repetidamente la עֶזְרָה de Yahvé como rescate urgente (Sal 22:20; 38:23; 40:14; 60:13; 70:2; 71:12). En la narrativa histórica, se refiere a refuerzo militar: Meroz es maldecido por negar su ayuda en la guerra santa (Jue 5:23), y Acaz descubre que la ''ayuda'' de Asiria resulta en realidad perjudicial (2 Cr 28:21). Concretamente, puede significar un auxiliador o refuerzo encarnado, como cuando Job lamenta que toda ayuda ha sido expulsada de él (Job 6:13; 31:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123487, 'spa', 'Nombre en genealogía', '1 Crónicas 4:17 registra a Ezrá en la genealogía de Judá: «Los hijos de Ezrá: Jéter, Mered, Éfer y Jalón.» Este Ezrá es distinto del célebre sacerdote y escriba. La genealogía lo sitúa dentro de la estructura tribal de Judá, preservando su linaje aunque no se conservan relatos sobre él. Los nombres de sus hijos quedaron registrados, manteniendo la memoria generacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123488, 'spa', 'Cornisa del altar', 'La cornisa o repisa que rodea el altar visionario de Ezequiel, un saliente horizontal que define los niveles del altar. Ezequiel 43:14 distingue ''la cornisa inferior'' (הָעֲזָרָה הַתַּחְתּוֹנָה) de ''la cornisa mayor'' (הָעֲזָרָה הַגְּדוֹלָה), y se aplica sangre de purificación en sus esquinas (Ez 43:20; 45:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123489, 'spa', 'Atrio del templo', 'El atrio o recinto cerrado del templo de Salomón. En 2 Crónicas 4:9 se refiere al ''gran atrio'' (הָעֲזָרָה הַגְּדוֹלָה) con sus puertas, y en 2 Crónicas 6:13 es el espacio donde Salomón colocó su plataforma de bronce. Comparte con la acepción de cornisa del altar el concepto fundamental de un espacio sagrado delimitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123494, 'spa', 'Oficial agrícola davídico', '1 Crónicas 27:26 enumera a Ezri entre los oficiales de David: «Ezri hijo de Quelub estaba a cargo de los trabajadores del campo que labraban la tierra.» El nombre aparece solo aquí. Como supervisor del trabajo agrícola, Ezri administraba a quienes cultivaban los campos, huertos y viñedos reales, un papel económico fundamental. Su inclusión en el registro administrativo evidencia la importancia de la agricultura para el reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123495, 'spa', 'Nombre propio teofórico', 'Tres individuos: un perseguidor de Jeremías, un jefe manasita y un administrador neftalita. El contexto de Jeremías es el más dramático: Azriel es enviado a capturar al profeta, pero la intervención divina frustra la misión. Las versiones de la Septuaginta varían en su transliteración, reflejando los desafíos típicos de trasladar nombres propios hebreos al griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123496, 'spa', 'Azarías (sumo sacerdote / alias del rey) — El nombre propio Azarías, que signifi', 'Azarías (sumo sacerdote / alias del rey) — El nombre propio Azarías, que significa ''Yah ha ayudado'', usado para múltiples individuos incluyendo al rey Azarías/Uzías de Judá (2 R 14:21; 15:1-7), el sumo sacerdote que se opuso a la ofrenda de incienso de Uzías (2 Cr 26:17-20), varias figuras sacerdotales en genealogías del Cronista (1 Cr 5:35-40; Esd 7:1-3), oficiales salomónicos (1 R 4:2, 5) y un líder postexílico (Neh 10:3). Su frecuencia refleja lo común que era el patrón teofórico de afirmar la ayuda divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123504, 'spa', 'Compañero de Daniel', 'Daniel 2:17 menciona a «Azarías» como compañero de Daniel, aunque después se le llama consistentemente Abednego. Diversas traducciones preservan el nombre Azarías, reconociéndolo como su nombre hebreo de nacimiento. El significado del nombre —«YHWH ha ayudado»— resultó profético cuando Dios lo libró del horno de Nabucodonosor. Su identidad dual refleja la tensión entre la fe israelita y la presión cultural babilónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123505, 'spa', 'Azricam (nombre propio)', 'Nombre masculino propio que significa ''mi ayuda se ha levantado'', designando a cuatro individuos en las genealogías postmonárquicas y uno en la narrativa monárquica. El portador más memorable es el mayordomo de palacio (נְגִיד הַבַּיִת) muerto durante el conflicto siro-efraimita (2 Cr 28:7). Las apariciones genealógicas en 1 Crónicas 3, 8-9 y Nehemías 11 demuestran la vigencia del nombre entre linajes davídicos, benjaminitas y levíticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123508, 'spa', 'Instrumento de escritura', 'Instrumento de escritura que puede ser un estilo de hierro para grabar superficies duras o una pluma de caña para escribir en rollos. Job 19:24 y Jeremías 17:1 especifican un עֵט de hierro con punta de diamante (בְּצִפֹּרֶן שָׂמִיר) para inscripciones permanentes. Jeremías 8:8 condena la «pluma mentirosa de los escribas». Salmo 45:1 compara metafóricamente la lengua con «la pluma de un escribiente diestro».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123509, 'spa', 'Consejo o decreto', 'Daniel 2:14 describe la indagación de Daniel ante Arioc sobre «el consejo/decreto» tan precipitado del rey. El término abarca tanto el sentido de consejo prudente como el de decisión autoritativa. El contexto es la crisis del decreto de muerte contra todos los sabios: Daniel busca comprender la decisión y su urgencia para intervenir con sabiduría y ofrecer una alternativa ante el rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123510, 'spa', 'Hifil: cubrir, vestir', 'Hifil causativo: hacer que alguien quede cubierto o vestido, con Dios o un agente poderoso como sujeto. En el Salmo 84:6 la lluvia temprana ''cubre'' la tierra, y en el Salmo 89:45 Dios ''lo ha cubierto de vergüenza''. El cubrir se convierte en un acto impuesto de juicio o bendición divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123511, 'spa', 'Qal: cubrir (transitivo)', 'Qal transitivo: cubrir o envolver a otra persona. El leproso ''cubrirá su labio superior'' (Lev 13:45), a Ezequiel se le ordena no ''cubrirse el labio'' en señal de duelo (Ez 24:17), y los líderes de Israel ''cubrirán sus labios'' de vergüenza (Miq 3:7). El enfoque recae en la acción directa de cubrir al otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123513, 'spa', 'Qal: envolverse, cubrirse', 'Qal reflexivo: envolverse o cubrirse con una prenda o cobertura. La sombra de Samuel asciende ''envuelta en un manto'' (1 Sam 28:14), los enemigos son maldecidos a quedar ''envueltos en vergüenza como en un manto'' (Sal 109:29), y Dios ''se envuelve de luz'' (Sal 104:2). La imagen central es la de arroparse reflexivamente con una vestidura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123526, 'spa', 'Recipientes de abundancia', 'Job 21:24 describe al próspero: «sus baldes están llenos de leche», una imagen de abundancia desbordante. El español «sus ubres» adopta un enfoque textual diferente, viendo el término como relacionado con la plenitud corporal en vez de recipientes. El contexto es la observación de Job de que algunos mueren en prosperidad, lo cual contradice la teología retributiva simplista que defienden sus amigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123527, 'spa', 'Estornudos del Leviatán', 'Job 41:18 describe al Leviatán: «Sus estornudos lanzan destellos de luz y sus ojos son como los párpados del alba.» El contexto es el discurso de YHWH desafiando a Job: ¿puedes tú dominar a este monstruo? Los estornudos que producen luz realzan el retrato sobrenatural de la criatura, subrayando que lo que Dios ha creado sobrepasa todo control humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123528, 'spa', 'Murciélago', 'Tres apariciones: dos en la legislación dietética levítica y una en la imaginería profética de Isaías. En la profecía, los murciélagos como criaturas de las tinieblas reciben los ídolos desechados, un destino apropiado para dioses falsos. La clasificación junto a las aves refleja la taxonomía fenomenológica antigua, basada en características observables como el vuelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123529, 'spa', 'Volverse, apartarse', 'Job 23:9 expresa la incapacidad de Job para percibir a Dios: «Se vuelve a la derecha y no lo veo; se vuelve a la izquierda y no lo percibo.» El contexto es el lamento de Job por la inaccesibilidad divina. Aunque busca a Dios con ahínco, Dios permanece inalcanzable, volviéndose siempre fuera de su alcance, lo que intensifica la angustia del sufriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123531, 'spa', 'debilitarse (Hifil)', 'Hifil causativo-factitivo: volverse o ser hecho débil. Génesis 30:42 lo emplea en una cláusula temporal — ''cuando el rebaño mostraba debilidad'' — para marcar la aparición de la debilidad como condición que desencadena la estrategia de cría selectiva de Jacob. El Hifil presenta la debilidad como un evento con inicio observable externamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123532, 'spa', 'desmayarse, desfallecer (Hitpael)', 'Hitpael reflexivo: sentir el desfallecimiento dentro de sí, desmayarse o quedar abrumado interiormente. Es la forma más frecuente, usada para el colapso espiritual y emocional: el alma desfalleciendo por el camino (Sal 107:5), el espíritu abrumado por dentro (Sal 142:3, 143:4) y los niños desmayándose en las plazas de la ciudad (Lam 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123533, 'spa', 'desfallecer, debilitarse (Qal)', 'Qal intransitivo: desfallecer, debilitarse. Usado en los encabezados de salmos (Sal 61:2, 102:1) para el estado del corazón abrumado, y en Isaías 57:16 donde Dios contiene el juicio para que ''el espíritu no desfallezca ante mí''. La raíz simple presenta el desfallecimiento como un estado llano, sin la intensificación reflexiva del Hitpael.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (123537, 'spa', 'los débiles (sustantivado)', 'Participio sustantivado: ''los débiles'', usado como sustantivo para clasificar a un grupo por su debilidad. En Génesis 30:42 Jacob separa las ovejas ''débiles'' de las ''fuertes''; en Lamentaciones 2:19, ''los que desfallecen de hambre'' se convierten en una categoría identificable de sufrientes.');